'use strict';

async function setConditionContext({call, verify, verifySources}) {
  let setConditionContextCases=0;
  for(const version of ['2.3','2.4']) {
    const wrap=body=>`INTERLIS ${version};CONTRACTED MODEL F AT "https://example.org" VERSION "1"=${body}END F.`;
    const signature='FUNCTION check(objects:OBJECTS OF ANYCLASS):BOOLEAN;';
    for(const expression of ['n>0','NOT (flag)','INTERLIS.len(label)>0','DEFINED(THIS)','F.check(THIS)','DEFINED(items[FIRST]->code)']) {
      await verify(wrap(signature+'STRUCTURE S=code:TEXT;END S;TOPIC T=CLASS C=n:0..10;flag:BOOLEAN;label:TEXT;items:LIST OF S;SET CONSTRAINT '+expression+';END C;END T;'),'rejected');
      setConditionContextCases++;
    }
    const filtered=wrap('TOPIC T=CLASS C=n:0..10;SET CONSTRAINT WHERE n>0:INTERLIS.objectCount(ALL)>=0;END C;END T;');
    await verifySources([{sourceId:'memory:/stabilization.ili',text:filtered}],'succeeded',['F'],async(sessionId,compiled)=>{
      const query=(offset,kind)=>call('query',sessionId,{snapshotId:compiled.snapshotId,query:{kind,sourceId:'memory:/stabilization.ili',revision:'1',startOffset:offset,endOffset:offset}});
      const declaration=await query(filtered.indexOf('n:0'),'symbolAt');
      const reference=await query(filtered.indexOf('WHERE n')+6,'definition');
      if(declaration.kind!=='known'||reference.kind!=='definition'||declaration.symbolId!==reference.symbolId)
        throw new Error('SET WHERE lost its individual attribute target '+JSON.stringify({declaration,reference}));
    });setConditionContextCases++;
    const cases=[
      ['TOPIC T=CLASS C=SET CONSTRAINT #true;END C;END T;',version==='2.3'?'succeeded':'rejected'],
      ['TOPIC T=CLASS C=SET CONSTRAINT INTERLIS.len("fixed")>0;END C;END T;',version==='2.3'?'succeeded':'rejected'],
      ['TOPIC T=CLASS C=SET CONSTRAINT WHERE INTERLIS.objectCount(ALL)>=0:#true;END C;END T;',version==='2.3'?'succeeded':'rejected'],
      [signature+'TOPIC T=CLASS C=MANDATORY CONSTRAINT F.check(THIS);MANDATORY CONSTRAINT F.check(ALL);CONSTRAINT >=90% F.check(THIS);CONSTRAINT >=90% F.check(ALL);SET CONSTRAINT F.check(ALL);END C;END T;','succeeded'],
      ['PARAMETER enabled:BOOLEAN;FUNCTION check(cls:CLASS;attr:ATTRIBUTE OF @cls):BOOLEAN;TOPIC T=CLASS C=label:TEXT;SET CONSTRAINT PARAMETER enabled AND F.check(>C,>>label) AND INTERLIS.objectCount(ALL)>=0;END C;END T;','succeeded'],
      ['TOPIC T=CLASS C=n:0..10;END C;CONSTRAINTS OF C=SET CONSTRAINT n>0;END;END T;','rejected'],
      ['TOPIC T=CLASS C=n:0..10;END C;CONSTRAINTS OF C=SET CONSTRAINT WHERE n>0:INTERLIS.objectCount(ALL)>=0;END;END T;','succeeded']
    ];
    for(const [body,expected]of cases){await verify(wrap(body),expected);setConditionContextCases++;}
    if(version==='2.4')for(const name of ['areAreas2','areAreas3'])for(const actual of ['ALL','THIS']) {
      await verify(wrap('DOMAIN P=COORD 0.000..10.000,0.000..10.000;TOPIC T=CLASS C=surface:SURFACE WITH(STRAIGHTS) VERTEX P WITHOUT OVERLAPS>0.010;'
        +(actual==='ALL'?'SET':'MANDATORY')+' CONSTRAINT INTERLIS.'+name+'('+actual+',UNDEFINED,"surface");END C;END T;'),'succeeded');setConditionContextCases++;
    }
  }
  // L2-1: dependent constants use actual roots and preserve their query targets.
  return setConditionContextCases;
}

async function dependentFunctions({call, verify, verifySources}) {
  let dependentFunctionCases=0;
  for(const version of ['2.3','2.4']) {
    const wrap=body=>`INTERLIS ${version};CONTRACTED MODEL F AT "x" VERSION "1"=${body}END F.`;
    const signature='FUNCTION check(objects:CLASS;attr:ATTRIBUTE OF @objects RESTRICTION(TEXT)):BOOLEAN;';
    for(const expression of ['>>label','(>>label)']) {
      const text=wrap(signature+'TOPIC T=CLASS Data=label:TEXT;END Data;CLASS Host=label:BOOLEAN;'
        +`MANDATORY CONSTRAINT F.check(>Data,${expression});END Host;END T;`);
      await verifySources([{sourceId:'memory:/stabilization.ili',text}],'succeeded',['F'],async(sessionId,compiled)=>{
        const query=(offset,kind)=>call('query',sessionId,{snapshotId:compiled.snapshotId,query:{kind,sourceId:'memory:/stabilization.ili',revision:'1',startOffset:offset,endOffset:offset}});
        const declaration=await query(text.indexOf('label:TEXT'),'symbolAt');
        const reference=await query(text.lastIndexOf('>>label')+2,'symbolAt');
        const definition=await query(text.lastIndexOf('>>label')+2,'definition');
        if(declaration.kind!=='known'||reference.kind!=='known'||definition.kind!=='definition'
            ||declaration.symbolId!==reference.symbolId||declaration.symbolId!==definition.symbolId)
          throw new Error('Dependent argument lost its actual attribute target '+JSON.stringify({declaration,reference,definition}));
      });dependentFunctionCases++;
    }
    const cases=[
      ['FUNCTION pick(objects:CLASS):ATTRIBUTE OF @objects RESTRICTION(TEXT);TOPIC T=CLASS Host=MANDATORY CONSTRAINT DEFINED(F.pick(UNDEFINED));END Host;END T;','succeeded'],
      ['FUNCTION objects(flag:BOOLEAN):OBJECTS OF ANYCLASS;FUNCTION pick(objects:OBJECTS OF ANYCLASS):ATTRIBUTE OF @objects RESTRICTION(TEXT);TOPIC T=CLASS Host=SET CONSTRAINT DEFINED(F.pick(F.objects(#true)));END Host;END T;','succeeded'],
      ['DOMAIN P=COORD 0.000..100.000,0.000..100.000;STRUCTURE S=surface:SURFACE WITH(STRAIGHTS) VERTEX P WITHOUT OVERLAPS>0.010;END S;TOPIC T=CLASS C=bag:BAG OF S;surface:BOOLEAN;SET CONSTRAINT INTERLIS.areAreas(ALL,>>bag,>>surface);END C;END T;','succeeded'],
      ['FUNCTION pick(objects:CLASS):ATTRIBUTE OF @objects RESTRICTION(TEXT);'+signature+'TOPIC T=CLASS Data=label:TEXT;END Data;CLASS Host=MANDATORY CONSTRAINT F.check(>Data,F.pick(>Data));END Host;END T;','succeeded'],
      [signature+'TOPIC T=CLASS C=cls:CLASS;path:ATTRIBUTE OF cls RESTRICTION(TEXT);MANDATORY CONSTRAINT F.check(cls,path);END C;END T;','succeeded'],
      ['FUNCTION check(attr:ATTRIBUTE OF @objects RESTRICTION(TEXT);objects:CLASS):BOOLEAN;TOPIC T=CLASS Data=label:TEXT;END Data;CLASS Host=MANDATORY CONSTRAINT F.check(>>label,>Data);END Host;END T;','succeeded'],
      [signature+'TOPIC T=CLASS Data=label:BOOLEAN;END Data;CLASS Host=MANDATORY CONSTRAINT F.check(>Data,>>label);END Host;END T;','rejected'],
      [signature+'TOPIC T=CLASS Host=label:TEXT;MANDATORY CONSTRAINT F.check(>Missing,>>label);END Host;END T;','rejected'],
      ['TOPIC T=CLASS A=value:(one,two);END A;CLASS B=value:(one,three);EXISTENCE CONSTRAINT value REQUIRED IN A:value;END B;END T;','rejected']
    ];
    for(const [body,expected] of cases){await verify(wrap(body),expected);dependentFunctionCases++;}
  }
  // L1-1: ordinary appendix-A structures and the approved TYPE MODEL profile.
  return dependentFunctionCases;
}

async function semanticFoundations({verify}) {
  let foundationCases = 0;
  for (const version of ['2.3', '2.4']) {
    const model = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    for (const name of ['LineGeometry', 'SurfaceEdge', 'SurfaceBoundary']) {
      await verify(model(`STRUCTURE Holder=value:INTERLIS.${name};END Holder;`), 'succeeded');
      await verify(model(`IMPORTS UNQUALIFIED INTERLIS;STRUCTURE Holder=value:${name};END Holder;`), 'succeeded');
      foundationCases += 2;
    }
    await verify(model('STRUCTURE Holder=value:SurfaceEdge;END Holder;'), 'rejected');
    await verify(model('STRUCTURE Holder=value:INTERLIS.surfaceEdge;END Holder;'), 'rejected');
    await verify(model('CLASS C(ABSTRACT)=END C;').replace('CONTRACTED MODEL', 'CONTRACTED TYPE MODEL'), 'succeeded');
    await verify(model('TOPIC T=END T;').replace('CONTRACTED MODEL', 'CONTRACTED TYPE MODEL'), 'rejected');
    foundationCases += 4;
  }
  // L1-2: exact subdivision relations and the explicitly approved numeric profiles.
  return foundationCases;
}

async function inheritanceFoundations({call, verify, verifySources}) {
  let inheritanceFoundationCases = 0;
  for (const version of ['2.3', '2.4']) {
    const model = (name,body) => `INTERLIS ${version}; CONTRACTED MODEL ${name} AT "https://example.org" VERSION "1" = ${body} END ${name}.`;
    const assoc = (base,child) => 'TOPIC T=OID AS INTERLIS.UUIDOID;CLASS A=END A;CLASS B=END B;'
      + `ASSOCIATION Root=left--{1}A;right--{1}B;value:${base};END Root;ASSOCIATION Child EXTENDS Root=value(EXTENDED):${child};END Child;END T;`;
    const abstractRoles = 'TOPIC T=OID AS INTERLIS.UUIDOID;CLASS A=END A;CLASS B=END B;'
      + 'ASSOCIATION Root(ABSTRACT)=left(ABSTRACT)--{1}A;right--{1}B;END Root;ASSOCIATION Child EXTENDS Root=END Child;END T;';
    const cases = [
      ['TOPIC A EXTENDS B=END A;TOPIC B EXTENDS A=END B;','rejected'],
      ['TOPIC T=CLASS Root(FINAL)=END Root;CLASS Child EXTENDS Root=END Child;END T;','rejected'],
      ['STRUCTURE Root(FINAL)=END Root;STRUCTURE Child EXTENDS Root=END Child;','rejected'],
      ['TOPIC Root(FINAL)=CLASS C=END C;END Root;TOPIC Child EXTENDS Root=END Child;','rejected'],
      ['STRUCTURE Root=value(FINAL):TEXT*10;END Root;STRUCTURE Child EXTENDS Root=value(EXTENDED):TEXT*5;END Child;','rejected'],
      ['STRUCTURE C=value(EXTENDED):TEXT*10;END C;','rejected'],
      [assoc('TEXT*5','TEXT*10'),'rejected'],
      [assoc('MANDATORY TEXT*10','TEXT*5'),'rejected'],
      [assoc('TEXT*10','TEXT*5'),'succeeded'],
      [assoc('TEXT*10','MANDATORY'),'succeeded'],
      [abstractRoles,'succeeded'],
      [abstractRoles.replace('EXTENDS Root=END Child','EXTENDS Root=left(EXTENDED)--{1}A;END Child'),'succeeded'],
      [abstractRoles.replace('Root(ABSTRACT)','Root'),'rejected'],
      [abstractRoles.replace('left(ABSTRACT)','left').replace('END Root;','value(ABSTRACT):TEXT*10;END Root;'),'rejected']
    ];
    for (const kind of ['CLASS','STRUCTURE']) cases.push([
      `TOPIC T=${kind} Root=alpha:TEXT*10;beta:0..10;END Root;${kind} Middle EXTENDS Root=alpha(EXTENDED):TEXT*5;middle:BOOLEAN;END Middle;`
      + `${kind} Leaf EXTENDS Middle=beta(EXTENDED):0..5;leaf:TEXT*3;END Leaf;END T;`,'succeeded']);
    for (const [body,expected] of cases) {await verify(model('F',body),expected);inheritanceFoundationCases++;}
    for (const baseFirst of [true,false]) for (const finalBase of [false,true]) {
      const baseId=`memory:/${baseFirst?'a':'z'}-base.ili`,useId=`memory:/${baseFirst?'z':'a'}-use.ili`;
      const base=model('F',`STRUCTURE Root=label:TEXT*10;END Root;STRUCTURE Middle${finalBase?'(FINAL)':''} EXTENDS Root=END Middle;`);
      const use=model('M','IMPORTS F;STRUCTURE Leaf EXTENDS F.Middle=label(EXTENDED):TEXT*5;END Leaf;');
      await verifySources([{sourceId:useId,text:use},{sourceId:baseId,text:base}],finalBase?'rejected':'succeeded',['M'],!finalBase?async(sessionId,compiled)=>{
        const query=(sourceId,offset,kind)=>call('query',sessionId,{snapshotId:compiled.snapshotId,query:{kind,sourceId,revision:'1',startOffset:offset,endOffset:offset}});
        const declaration=await query(baseId,base.indexOf('Middle'),'symbolAt');
        const reference=await query(useId,use.indexOf('F.Middle')+2,'symbolAt');
        const definition=await query(useId,use.indexOf('F.Middle')+2,'definition');
        if(declaration.kind!=='known'||reference.kind!=='known'||definition.kind!=='definition'
            ||declaration.symbolId!==reference.symbolId||declaration.symbolId!==definition.symbolId)
          throw new Error('Imported inheritance lost its actual base '+JSON.stringify({declaration,reference,definition}));
      }:undefined);
      inheritanceFoundationCases++;
    }
  }
  // L0B-3: legacy function annotations retain source validity in every backend.
  return inheritanceFoundationCases;
}

async function versionedFunctionsAndDomains({verify}) {
  const functions = [
    ['2.3', true, '(v: BOOLEAN): BOOLEAN', 'f(#true, #false)', 'rejected'],
    ['2.3', true, '(v: BOOLEAN): BOOLEAN', 'f(123)', 'rejected'],
    ['2.3', true, '(v: NUMERIC): NUMERIC', 'f(1) > 0', 'succeeded'],
    ['2.3', false, '(v: BOOLEAN): BOOLEAN', 'f(#true)', 'rejected'],
    ['2.4', false, '(v: BOOLEAN): BOOLEAN', 'f(#true)', 'succeeded'],
    ['2.4', true, '(v: BOOLEAN): BOOLEAN', 'F.f(#true)', 'succeeded'],
    ['2.3', true, '(v: BOOLEAN): BOOLEAN', 'INTERLIS.len("abc") >= 0', 'succeeded'],
    ['2.4', false, '(v: BOOLEAN): BOOLEAN', 'INTERLIS.trim(" abc ") == "abc"', 'succeeded'],
    ['2.4', false, '(v: BOOLEAN): BOOLEAN', 'INTERLIS.len(123) >= 0', 'rejected'],
    ['2.3', true, '(v: BOOLEAN): BOOLEAN', 'INTERLIS.len("abc", "def") >= 0', 'rejected'],
    ['2.4', false, '(v: BOOLEAN): BOOLEAN', 'INTERLIS.unknownBoolean()', 'rejected']
  ];
  for (const [version, contracted, signature, expression, expected] of functions) {
    await verify(`INTERLIS ${version}; ${contracted ? 'CONTRACTED ' : ''}
MODEL F AT "x" VERSION "1" = FUNCTION f ${signature};
TOPIC T = CLASS C = MANDATORY CONSTRAINT ${expression}; END C; END T; END F.`, expected);
  }
  const domains = [
    ['2.4', 'TEXT*30', 'INTERLIS.len(THIS) > 2', 'succeeded'],
    ['2.4', '0..100', 'THIS > 10', 'succeeded'],
    ['2.4', 'TEXT*30', 'THIS > 10', 'rejected'],
    ['2.4', '0..100', 'THIS', 'rejected'],
    ['2.3', '0..100', 'THIS > 10', 'rejected']
  ];
  for (const [version, type, expression, expected] of domains) {
    await verify(`INTERLIS ${version}; MODEL F AT "x" VERSION "1" =
DOMAIN Value = ${type} CONSTRAINTS CheckValue: ${expression}; END F.`, expected);
  }
  return functions.length + domains.length;
}

async function valueFamilies({verify}) {
  let valueFamilyCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const exists = (defs, from, to) => `TOPIC T = ${defs} CLASS A = value: ${to}; END A;
CLASS B = value: ${from}; EXISTENCE CONSTRAINT value REQUIRED IN A:value; END B; END T;`;
    const enumeration = `DOMAIN Base = (red, green, blue) ORDERED;
More EXTENDS Base = (red(dark, light: FINAL), yellow); Last EXTENDS More = (blue(pale));`;
    const rows = [[exists(enumeration, 'Last', 'Base'), 'succeeded'],
      [`TOPIC T = ${enumeration} CLASS A = value: Last; MANDATORY CONSTRAINT value == #green; END A; END T;`, 'succeeded'],
      [`TOPIC T = ${enumeration} CLASS A = value: Last; MANDATORY CONSTRAINT value == #red; END A; END T;`, 'rejected']];
    for (const defs of ['Base = (a,b: FINAL); More EXTENDS Base = (c);',
      'Base = (a(x,y: FINAL),b); More EXTENDS Base = (a(z));',
      'Base = (a,b) CIRCULAR; More EXTENDS Base = (c);', 'Base = (a,b); More EXTENDS Base = (a);',
      'Base EXTENDS Base = (a,b);', 'Base = (a,b); More EXTENDS Base = (a.new);'])
      rows.push([`TOPIC T = DOMAIN ${defs} END T;`, 'rejected']);
    rows.push(['TOPIC T = DOMAIN Base = (a,b: FINAL); More EXTENDS Base = (a(x,y)); END T;', 'succeeded'],
      ['TOPIC T = DOMAIN Base = (a(x,y),b); More EXTENDS Base = (a(FINAL)); END T;', 'succeeded']);
    const attr = `TOPIC T = CLASS A = value: (a,b) ORDERED; END A; CLASS B EXTENDS A =
value (EXTENDED): (a(x,y)); MANDATORY CONSTRAINT value == #b; END B; END T;`;
    rows.push([attr, 'succeeded'], [attr.replace('(a,b) ORDERED', '(a,b: FINAL) ORDERED').replace('(a(x,y))', '(c)'), 'rejected']);
    rows.push([exists('DOMAIN Id = OID TEXT*36;', 'Id', 'Id'), 'succeeded'],
      [exists('', 'OID 0..999', 'OID 0..10'), 'succeeded'], [exists('', 'OID TEXT*30', 'OID TEXT*10'), 'succeeded'],
      [exists('', 'OID ANY', 'OID TEXT*10'), 'succeeded'], [exists('', 'OID 0..10', 'OID TEXT*10'), 'rejected'],
      [exists('', 'INTERLIS.UUIDOID', 'INTERLIS.UUIDOID'), 'succeeded'],
      [exists('', 'INTERLIS.UUIDOID', 'UUIDOID'), 'rejected'],
      [exists('DOMAIN UUIDOID = OID TEXT*36;', 'UUIDOID', 'UUIDOID'), 'succeeded'],
      ['TOPIC T = DOMAIN Id EXTENDS INTERLIS.ANYOID = TEXT*10; END T;', 'rejected'],
      ['TOPIC T = DOMAIN Id EXTENDS Missing = OID TEXT*10; END T;', 'rejected'],
      ['TOPIC T = DOMAIN Base = OID ANY; Id EXTENDS Missing.Base = OID TEXT*10; END T;', 'rejected'], [exists('', 'INTERLIS.I32OID', 'INTERLIS.ANYOID'), 'succeeded'],
      ['TOPIC T = DOMAIN Id = OID TEXT*36; Narrow EXTENDS Id = OID TEXT*10; END T;', 'rejected'],
      ['TOPIC T = DOMAIN Id EXTENDS INTERLIS.ANYOID = OID TEXT*10; END T;', 'succeeded'],
      ['TOPIC T = DOMAIN Id EXTENDS INTERLIS.I32OID = OID 0..10; END T;', 'rejected']);
    const structures = 'STRUCTURE S = code: TEXT; END S; STRUCTURE Child EXTENDS S = number: 0..10; END Child; STRUCTURE Other = code: TEXT; END Other;';
    for (const kind of ['BAG', 'LIST']) rows.push([exists(structures, `${kind} {0..10} OF Child`, `${kind} {1..2} OF S`), 'succeeded'],
      [exists(structures, `${kind} OF Other`, `${kind} OF S`), 'rejected']);
    rows.push([exists(structures,'BAG OF S','LIST OF S'), 'rejected'], [exists(structures,'BAG OF S','S'), 'rejected'],
      [exists(structures,'BAG OF S','BAG OF S').replace('value REQUIRED','value->code REQUIRED'), 'rejected'],
      [exists('', 'LIST {0..9} OF 0..999','LIST {1..2} OF 0..10'), version === '2.4' ? 'succeeded' : 'rejected'],
      [exists('', 'LIST OF TEXT','LIST OF 0..10'), 'rejected']);
    const formatDefs = 'STRUCTURE S = major: 0..99; minor: 0..9; END S; DOMAIN Code = FORMAT BASED ON S (major/2 "-" minor); Small = FORMAT Code "01-0" .. "20-9";';
    const format = exists(formatDefs, 'Code', 'Small');
    rows.push([format,'succeeded'], [format.replace('major/2','missing/2'),'rejected'],
      [format.replace('major: 0..99','major: TEXT'),'rejected'], [format.replace('major/2','major/0'),'rejected'],
      [format.replace('"20-9"','"100-9"'),'rejected'], [format.replace('"01-0"','"21-0"'),'rejected']);
    const nested = `TOPIC T = STRUCTURE S = number: 0..99; END S; DOMAIN Code = FORMAT BASED ON S (number/2);
STRUCTURE Container = nested: S; extra: 0..9; END Container;
DOMAIN Pair = FORMAT BASED ON Container (nested/Code "-" extra);
STRUCTURE Extended EXTENDS S = suffix: 0..9; END Extended;
DOMAIN ExtendedCode EXTENDS Code = FORMAT BASED ON Extended (INHERITANCE "-" suffix); END T;`;
    rows.push([nested,'succeeded'], [nested.replace('nested: S','nested: BAG OF S'),'rejected'],
      [nested.replace('nested/Code','nested/Missing'),'rejected'], [nested.replace('INHERITANCE',''),'rejected']);
    const bounds = 'TOPIC T = STRUCTURE S = number: 0..99; END S; DOMAIN Code = FORMAT BASED ON S (number) "10" .. "30"; Narrow EXTENDS Code = "12" .. "20"; END T;';
    rows.push([bounds,'succeeded'], [bounds.replace('"12"','"09"'),'rejected'],
      [exists('', 'FORMAT INTERLIS.XMLDate "2010-01-01" .. "2110-12-31"','INTERLIS.XMLDate'),'succeeded'],
      [exists('', 'INTERLIS.XMLDate','INTERLIS.XMLTime'),'rejected']);
    const inheritedBounds = 'TOPIC T = STRUCTURE S = number: 0..99; END S; DOMAIN Code = FORMAT BASED ON S (number) "10" .. "30"; STRUCTURE More EXTENDS S = extra: 0..9; END More; DOMAIN Pair EXTENDS Code = FORMAT BASED ON More (INHERITANCE "-" extra); Narrow EXTENDS Pair = "12-1" .. "20-1"; END T;';
    rows.push([inheritedBounds,'succeeded'], [inheritedBounds.replace('"12-1"','"09-1"'),'rejected']);
    if (version === '2.4') rows.push([exists('', 'DATE','INTERLIS.XMLDate'),'succeeded']);
    for (const [body, expected] of rows) { await verify(wrap(body), expected); valueFamilyCases++; }
  }
  return valueFamilyCases;
}

async function formattedValuesAndOid({verify}) {
  let formatOidCases = 0;
  for (const version of ['2.3','2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const numeric = (type,width,lo,hi) => `TOPIC T = STRUCTURE S = n: ${type}; END S; DOMAIN Code = FORMAT BASED ON S (n${width}) "${lo}" .. "${hi}"; END T;`;
    const rows = [
      [numeric('0.00..99.99','/2','01.20','20.00'),'succeeded'],
      [numeric('0.00..99.99','/2','1.20','20.00'),'rejected'],
      [numeric('0.00..99.99','/2','01.2','20.00'),'rejected'],
      [numeric('0.00..99.99','/2','01.201','20.00'),'rejected'],
      [numeric('-99.99..99.99','/2','-01.20','20.00'),'succeeded'],
      [numeric('0.00..9007199254740993.99','','9007199254740993.01','9007199254740993.02'),'succeeded'],
      [numeric('0.00..9007199254740993.99','','9007199254740993.02','9007199254740993.01'),'rejected'],
      [numeric('0..99','/99999999999999999999999','01','20'),'rejected'],
      [numeric('0.10e1..0.99e3','','0.12e2','0.90e3'),'succeeded'],
      [numeric('0.10e1..0.99e3','','0.123e2','0.90e3'),'rejected'],
      [numeric('0.10e1..0.99e3','','1.20e1','0.90e3'),'rejected'],
      [numeric('0.10e1..0.99e3','','12.00','900.00'),'rejected'],
      [numeric('0.00..99.99','','0.12e2','0.90e1'),'rejected']];
    const nested = `TOPIC T = STRUCTURE S = n: 0..99; END S;
DOMAIN Code = FORMAT BASED ON S (n/2) "10" .. "20";
STRUCTURE More EXTENDS S = extra: 0..9; END More;
DOMAIN Child EXTENDS Code = FORMAT BASED ON More (INHERITANCE "-" extra);
STRUCTURE Container = item: More; number: 0..9; END Container;
DOMAIN Pair = FORMAT BASED ON Container (item/Child "/" number) "12-1/0" .. "18-9/9";
CLASS A = value: Pair; MANDATORY CONSTRAINT value == "15-5/5"; END A; END T;`;
    rows.push([nested,'succeeded'],[nested.replace('12-1/0','09-1/0'),'rejected'],
      [nested.replace('18-9/9','21-9/9'),'rejected'],[nested.replace('15-5/5','09-5/5'),'rejected'],
      [nested.replace('15-5/5','19-5/5'),'rejected']);
    const date = 'TOPIC T = DOMAIN D = FORMAT INTERLIS.XMLDate "2010-01-01" .. "2020-12-31"; END T;';
    rows.push([date,'succeeded'],[date.replace('2010-01-01','2010-1-1'),version === '2.3' ? 'succeeded' : 'rejected'],[date.replace('2010-01-01','2010-01-32'),'rejected']);
    const time = 'TOPIC T = DOMAIN D = FORMAT INTERLIS.XMLTime "00:00:00.000" .. "23:59:59.999"; END T;';
    rows.push([time,'succeeded'],[time.replace('00:00:00.000','00:00:00.0001'),'rejected']);
    rows.push(['DOMAIN BasketId = OID TEXT*16; ObjectId = OID TEXT*36; TOPIC T = BASKET OID AS BasketId; OID AS ObjectId; CLASS A = END A; CLASS B = NO OID; END B; END T;','succeeded'],
      ['TOPIC T = CLASS A = OID AS INTERLIS.UUIDOID; END A; CLASS B = END B; END T;','succeeded'],
      ['TOPIC T = CLASS A = OID AS Missing; END A; END T;','rejected'],
      ['DOMAIN Id = TEXT*36; TOPIC T = CLASS A = OID AS Id; END A; END T;','rejected'],
      ['DOMAIN Id = OID TEXT*36; TOPIC T = CLASS A = OID AS Missing.Id; END A; END T;','rejected']);
    const inherited = 'TOPIC T = CLASS A (ABSTRACT) = OID AS INTERLIS.ANYOID; END A; CLASS B EXTENDS A = OID AS INTERLIS.UUIDOID; END B; END T;';
    rows.push([inherited,'succeeded'],[inherited.replace('CLASS A (ABSTRACT)','CLASS A'),'rejected'],
      [inherited.replace('OID AS INTERLIS.UUIDOID','NO OID'),'rejected'],
      [inherited.replace('INTERLIS.ANYOID','INTERLIS.STANDARDOID'),'rejected'],
      ['TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; END T; TOPIC U EXTENDS T = CLASS B = END B; END U;','succeeded'],
      ['TOPIC T = OID AS INTERLIS.UUIDOID; END T; TOPIC U EXTENDS T = OID AS INTERLIS.STANDARDOID; END U;','rejected']);
    const association = 'TOPIC T = CLASS A = OID AS INTERLIS.STANDARDOID; END A; CLASS B = OID AS INTERLIS.STANDARDOID; END B; ASSOCIATION Link = OID AS INTERLIS.UUIDOID; a -- A; b -- B; END Link; END T;';
    const multiple = association.replace('END Link;','CARDINALITY = {2}; END Link;');
    rows.push([association,'succeeded'],[multiple,'succeeded'],
      [multiple.replace('OID AS INTERLIS.UUIDOID;','NO OID;'),'rejected'],
      [multiple.replace('OID AS INTERLIS.UUIDOID;',''),'rejected'],
      ['DOMAIN Id = OID TEXT*36; TOPIC T = CLASS A = OID AS Id; END A; CLASS B EXTENDS A = OID AS Id; END B; END T;','succeeded'],
      ['TOPIC T = CLASS A = OID AS INTERLIS.NOOID; END A; END T;',version === '2.4' ? 'succeeded' : 'rejected'],
      ['TOPIC T = NO OID; END T;','rejected'],
      ['TOPIC T = OID AS INTERLIS.UUIDOID; STRUCTURE S = END S; CLASS A EXTENDS S = NO OID; END A; END T;','succeeded'],
      ['TOPIC T = CLASS A = END A; CLASS B EXTENDS A = OID AS INTERLIS.UUIDOID; END B; END T;',version === '2.3' ? 'succeeded' : 'rejected'],
      ['TOPIC T = CLASS A = END A; CLASS B (ABSTRACT) EXTENDS A = OID AS INTERLIS.ANYOID; END B; END T;','rejected'],
      ['TOPIC T (ABSTRACT) = CLASS A = END A; CLASS B (ABSTRACT) EXTENDS A = OID AS INTERLIS.ANYOID; END B; END T;','succeeded']);
    for (const [body,expected] of rows) { await verify(wrap(body),expected); formatOidCases++; }
    await verify(wrap(association).replace('CONTRACTED ',''), 'succeeded'); formatOidCases++;
    const original = 'DOMAIN FirstId = OID TEXT*36; SecondId = OID TEXT*36; TOPIC T = BASKET OID AS FirstId; OID AS SecondId; CLASS A = END A; END T;';
    const translation = body => wrap(body).replace(`INTERLIS ${version}; `,'').replace('VERSION "1" =','VERSION "1" TRANSLATION OF Base ["1"] =');
    const originalModel = body => wrap(body).replace('MODEL F ','MODEL Base ').replace('END F.','END Base.');
    const translated = translation(original.replaceAll('FirstId','Un').replaceAll('SecondId','Deux'));
    await verify(originalModel(original) + translated,'succeeded'); formatOidCases++;
    await verify(originalModel(original) + translated.replace('OID AS Deux','OID AS Un'),'rejected'); formatOidCases++;
    const builtin = 'TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; END T;';
    await verify(originalModel(builtin) + translation(builtin),'succeeded'); formatOidCases++;

  }
  return formatOidCases;
}

async function oidRestrictions({verify}) {
  let oidFollowupCases = 0;
  for (const version of ['2.3','2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const abstract = 'STRUCTURE S (ABSTRACT) = n (ABSTRACT): NUMERIC; END S; DOMAIN Code (ABSTRACT) = FORMAT BASED ON S (n/2); ';
    const concrete = abstract + 'STRUCTURE Concrete EXTENDS S = n (EXTENDED): 0.00..99.99; tail: 0..9; END Concrete; DOMAIN Value EXTENDS Code = FORMAT BASED ON Concrete (INHERITANCE "-" tail) "01.20-0" .. "20.00-9"; TOPIC T = CLASS A = value: Value; MANDATORY CONSTRAINT value == "12.34-5"; END A; END T;';
    const bounded = concrete.replace('(n/2);','(n/2) "01" .. "20";');
    const nested = abstract + 'STRUCTURE Box (ABSTRACT) = item (ABSTRACT): S; END Box; DOMAIN Wrapped (ABSTRACT) = FORMAT BASED ON Box (item/Code);';
    const explicit = 'TOPIC T (ABSTRACT) = CLASS A = NO OID; END A; CLASS B (ABSTRACT) EXTENDS A = OID AS INTERLIS.ANYOID; END B; END T;';
    const topics = 'TOPIC T (ABSTRACT) = OID AS INTERLIS.ANYOID; END T; TOPIC U (ABSTRACT) EXTENDS T = OID AS INTERLIS.UUIDOID; END U;';
    const rows = [
      ['STRUCTURE S = id: INTERLIS.NOOID; END S;',version === '2.4' ? 'succeeded' : 'rejected'],
      [explicit,version === '2.4' ? 'succeeded' : 'rejected'],
      [explicit.replace('CLASS B (ABSTRACT)','CLASS B').replace('INTERLIS.ANYOID','INTERLIS.UUIDOID'),'rejected'],
      [explicit.replace('OID AS INTERLIS.ANYOID','NO OID'),'succeeded'],
      [topics,'rejected'],[topics.replace('INTERLIS.UUIDOID','INTERLIS.ANYOID'),'succeeded'],
      ['DOMAIN D EXTENDS INTERLIS.ANYOID = OID TEXT*36;','succeeded'],
      ['DOMAIN D EXTENDS INTERLIS.UUIDOID = OID TEXT*36;','rejected'],
      ['DOMAIN D (ABSTRACT) EXTENDS D = OID ANY;','rejected'],
      [abstract,'succeeded'],[abstract.replace('Code (ABSTRACT)','Code'),'rejected'],
      [abstract + 'STRUCTURE Holder = value: Code; END Holder;','rejected'],
      [abstract + 'STRUCTURE Holder (ABSTRACT) = value (ABSTRACT): Code; END Holder;','succeeded'],
      [abstract.replace('(n/2);','(n/2) "01" .. "20";'),'succeeded'],
      [concrete,'succeeded'],[concrete.replace('01.20','01.2'),'rejected'],
      [concrete.replace('12.34','12.3'),'rejected'],
      [concrete.replace('n (EXTENDED): 0.00..99.99;',''),'rejected'],
      [bounded,'succeeded'],[bounded.replace('20.00-9','21.00-9'),'rejected'],
      [bounded.replace('01.20-0','00.20-0'),'rejected'],
      [bounded.replace('"01" .. "20"','"20" .. "01"'),'rejected'],
      [bounded.replace('"01" .. "20"','"1" .. "20"'),'rejected'],
      [nested,'succeeded'],[nested.replace('Wrapped (ABSTRACT)','Wrapped'),'rejected'],
      [nested + 'STRUCTURE H = value: Wrapped; END H;','rejected']
    ];
    if (version === '2.4') rows.push(
      ['DOMAIN D EXTENDS INTERLIS.NOOID = OID TEXT*36;','rejected'],
      ['DOMAIN D (ABSTRACT) EXTENDS INTERLIS.NOOID = OID ANY;','rejected']);
    for (const [body,expected] of rows) { await verify(wrap(body),expected); oidFollowupCases++; }
  }
  return oidFollowupCases;
}

async function noOidReferences({verify}) {
  let noOidReferenceCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const reference = (oid, target = 'A') => `TOPIC T = CLASS A = ${oid} END A; STRUCTURE S = value: REFERENCE TO ${target}; END S; END T;`;
    const role = (oid, target = 'A') => `TOPIC T = CLASS A = ${oid} END A; CLASS Owner = OID AS INTERLIS.UUIDOID; END Owner; ASSOCIATION Link = a -- ${target}; b -- Owner; END Link; END T;`;
    const withoutOid = version === '2.3' ? 'succeeded' : 'rejected';
    const rows = [];
    for (const build of [reference, role]) {
      rows.push([build(''), withoutOid], [build('NO OID;'), withoutOid],
        [build('OID AS INTERLIS.UUIDOID;'), 'succeeded'],
        [build('').replace('TOPIC T =', 'TOPIC T = OID AS INTERLIS.UUIDOID;'), 'succeeded'],
        [build('').replace('TOPIC T =', 'TOPIC T = BASKET OID AS INTERLIS.UUIDOID;'), withoutOid],
        [build('NO OID;').replace('TOPIC T =', 'TOPIC T = OID AS INTERLIS.UUIDOID;'), withoutOid],
        [build('', 'ANYCLASS'), 'succeeded']);
    }
    rows.push([reference('NO OID;', '(EXTERNAL) A'), withoutOid],
      [role('NO OID;').replace('a --', 'a (EXTERNAL) --'), withoutOid]);
    const association = 'TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; CLASS B = END B; ASSOCIATION Link = NO OID; a -- A; b -- B; END Link; STRUCTURE S = value: REFERENCE TO Link; END S; END T;';
    rows.push([association, 'rejected'], [association.replace('NO OID;', 'OID AS INTERLIS.UUIDOID;'), 'succeeded'],
      [association.replace('STRUCTURE S = value: REFERENCE TO Link; END S;', 'ASSOCIATION Meta = value -- Link; other -- A; END Meta;'), 'rejected'],
      [association.replace('NO OID;', '').replace('ASSOCIATION Link =', 'ASSOCIATION Link (OID) ='), 'succeeded']);
    const crossTopic = 'TOPIC Base = OID AS INTERLIS.UUIDOID; CLASS A = END A; END Base; TOPIC T = DEPENDS ON Base; STRUCTURE S = r: REFERENCE TO (EXTERNAL) Base.A; END S; END T;';
    rows.push([crossTopic, 'succeeded'], [crossTopic.replace('(EXTERNAL) ', ''), 'rejected'],
      [crossTopic.replace('Base.A', 'ANYCLASS RESTRICTION (Base.A)'), 'succeeded'],
      [crossTopic.replace('(EXTERNAL) Base.A', 'ANYCLASS RESTRICTION (Base.A)'), 'rejected'],
      [crossTopic.replace('TOPIC T = DEPENDS ON Base;', 'TOPIC T EXTENDS Base =').replace('(EXTERNAL) Base.A', 'A'), 'succeeded']);
    if (version === '2.4') rows.push([crossTopic.replace('(EXTERNAL) ', '').replace('r: REFERENCE', 'r: LIST OF REFERENCE'), 'rejected']);
    const narrowed = 'TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; CLASS B EXTENDS A = END B; STRUCTURE S = r: REFERENCE TO A; END S; STRUCTURE C EXTENDS S = r (EXTENDED): REFERENCE TO A RESTRICTION (B); END C; END T;';
    rows.push([narrowed, 'succeeded'], [narrowed.replace('REFERENCE TO A; END S;', 'REFERENCE TO A RESTRICTION (B); END S;').replace('REFERENCE TO A RESTRICTION (B); END C;', 'REFERENCE TO A; END C;'), 'rejected']);
    if (version === '2.4') {
      const sets = 'TOPIC T (ABSTRACT) = CLASS Root = NO OID; END Root; CLASS Stable (ABSTRACT) EXTENDS Root = OID AS INTERLIS.ANYOID; END Stable; CLASS Concrete EXTENDS Stable = OID AS INTERLIS.UUIDOID; flag: BOOLEAN; END Concrete; CLASS Other = NO OID; END Other; CLASS Owner = OID AS INTERLIS.UUIDOID; END Owner; ';
      rows.push([reference('OID AS INTERLIS.NOOID;'), 'rejected'], [role('OID AS INTERLIS.NOOID;'), 'rejected'],
        [sets + 'ASSOCIATION Link = a -- Root RESTRICTION (Stable); b -- Owner; END Link; END T;', 'succeeded'],
        [sets + 'ASSOCIATION Link = a -- Stable OR Other; b -- Owner; END Link; END T;', 'rejected'],
        [sets + 'ASSOCIATION Link = a -- ANYCLASS RESTRICTION (Stable; Other); b -- Owner; END Link; END T;', 'rejected'],
        [sets + 'STRUCTURE S = r: REFERENCE TO ANYCLASS RESTRICTION (Concrete); MANDATORY CONSTRAINT r->flag; END S; END T;', 'succeeded'],
        [sets + 'STRUCTURE S = r: REFERENCE TO ANYCLASS RESTRICTION (Concrete; Other); END S; END T;', 'rejected'],
        [sets + 'STRUCTURE S = r: REFERENCE TO Concrete RESTRICTION (Owner); END S; END T;', 'rejected'],
        [reference('NO OID;').replace('value: REFERENCE', 'value: BAG OF REFERENCE'), 'rejected'],
        [reference('OID AS INTERLIS.UUIDOID;').replace('value: REFERENCE', 'value: BAG OF REFERENCE'), 'succeeded']);
      const extended = 'TOPIC T (ABSTRACT) = CLASS A (ABSTRACT) = OID AS INTERLIS.ANYOID; END A; CLASS Owner = OID AS INTERLIS.UUIDOID; END Owner; ASSOCIATION Link = a -- A; owner -- Owner; END Link; END T; TOPIC U EXTENDS T = CLASS A (EXTENDED) = OID AS INTERLIS.UUIDOID; END A; STRUCTURE S = value: REFERENCE TO A; END S; END U;';
      rows.push([extended, 'succeeded'], [extended.replace('OID AS INTERLIS.UUIDOID; END A;', 'NO OID; END A;'), 'rejected']);
    }
    for (const [body, expected] of rows) { await verify(wrap(body), expected); noOidReferenceCases++; }
  }
  return noOidReferenceCases;
}

async function mandatoryConstraints({verify}) {
  let mandatoryCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const rows = [];
    const reference = 'TOPIC A = OID AS INTERLIS.UUIDOID; CLASS Target = flag: BOOLEAN; END Target; END A; TOPIC Base = DEPENDS ON A; STRUCTURE S = ref: REFERENCE TO (EXTERNAL) F.A.Target; END S; END Base; TOPIC T = DEPENDS ON A; STRUCTURE Child EXTENDS F.Base.S = ref (EXTENDED): MANDATORY; MANDATORY CONSTRAINT ref->flag; END Child; END T;';
    rows.push([reference,'succeeded'],[reference.replace('ref->flag;','ref->missing;'),'rejected'],[reference.replace('ref->flag;','ref->flag > 0;'),'rejected']);
    for (const kind of ['CLASS','STRUCTURE']) {
      const scalar = `DOMAIN Label = TEXT*20; FUNCTION truth(v: BOOLEAN): BOOLEAN; TOPIC T = ${kind} Base = flag: BOOLEAN; label: F.Label; number: 0..100; END Base; ${kind} Middle EXTENDS Base = flag (EXTENDED): MANDATORY; label (EXTENDED): MANDATORY; number (EXTENDED): MANDATORY; END Middle; ${kind} Child EXTENDS Middle = flag (EXTENDED): MANDATORY; label (EXTENDED): MANDATORY; number (EXTENDED): MANDATORY; MANDATORY CONSTRAINT truth(flag) AND INTERLIS.len(label) > 0 AND number > 2; END Child; END T;`;
      rows.push([scalar,'succeeded'],[scalar.replace('truth(flag)','truth(number)'),'rejected']);
    }
    const collection = 'TOPIC T = STRUCTURE Item = code: 0..100; END Item; CLASS Required = code: 0..100; END Required; CLASS Base = detail: Item; items: LIST {1..3} OF Item; END Base; CLASS Child EXTENDS Base = detail (EXTENDED): MANDATORY; items (EXTENDED): MANDATORY; MANDATORY CONSTRAINT items[FIRST]->code > 0; UNIQUE detail->code; UNIQUE (LOCAL) items: code; EXISTENCE CONSTRAINT detail->code REQUIRED IN Required: code; END Child; END T;';
    rows.push([collection,'succeeded'],[collection.replace('items[FIRST]','items[4]'),'rejected'],[collection.replace('UNIQUE detail->code','UNIQUE detail->missing'),'rejected'],[collection.replace('Required: code','Required: missing'),'rejected']);
    const extended = 'TOPIC Base = CLASS C = flag: BOOLEAN; END C; END Base; TOPIC T EXTENDS Base = CLASS C (EXTENDED) = flag (EXTENDED): MANDATORY; MANDATORY CONSTRAINT flag; END C; CONSTRAINTS OF C = MANDATORY CONSTRAINT flag; END; END T;';
    rows.push([extended,'succeeded'],[extended.replaceAll('CONSTRAINT flag;','CONSTRAINT flag > 0;'),'rejected']);
    const association = 'TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; CLASS B = END B; ASSOCIATION Link = a -- A; b -- B; flag: BOOLEAN; END Link; ASSOCIATION Child EXTENDS Link = flag (EXTENDED): MANDATORY; MANDATORY CONSTRAINT flag; END Child; END T;';
    rows.push([association,'succeeded'],[association.replace('CONSTRAINT flag;','CONSTRAINT flag > 0;'),'rejected']);
    const typed = 'TOPIC T = CLASS Base = value: BOOLEAN; END Base; CLASS Child EXTENDS Base = value (EXTENDED): NUMERIC; END Child; END T;';
    rows.push([typed,'rejected'],[typed.replace(': NUMERIC',': MANDATORY NUMERIC'),'rejected']);
    const structureBase = 'TOPIC T = STRUCTURE S = flag: BOOLEAN; END S; CLASS Child EXTENDS S = flag (EXTENDED): MANDATORY; MANDATORY CONSTRAINT flag; END Child; END T;';
    rows.push([structureBase,'succeeded']);
    for (const body of [
      'TOPIC T = CLASS C = value: MANDATORY; END C; END T;',
      'TOPIC T = CLASS C = value (EXTENDED): MANDATORY; END C; END T;',
      'TOPIC T = CLASS Base = value: BOOLEAN; END Base; CLASS C EXTENDS Base = value: MANDATORY; END C; END T;',
      'TOPIC T = STRUCTURE S = other: BOOLEAN; END S; STRUCTURE C EXTENDS S = value (EXTENDED): MANDATORY; END C; END T;',
      'TOPIC T = STRUCTURE S EXTENDS C = value (EXTENDED): MANDATORY; END S; STRUCTURE C EXTENDS S = value (EXTENDED): MANDATORY; END C; END T;'
    ]) rows.push([body,'rejected']);
    const restricted = 'TOPIC T = OID AS INTERLIS.UUIDOID; CLASS A = END A; CLASS B EXTENDS A = flag: BOOLEAN; END B; STRUCTURE Base = ref: REFERENCE TO ANYCLASS RESTRICTION (B); END Base; STRUCTURE Child EXTENDS Base = ref (EXTENDED): MANDATORY; MANDATORY CONSTRAINT ref->flag; END Child; END T;';
    rows.push([restricted,'succeeded'],[restricted.replace('RESTRICTION (B)','RESTRICTION (A)'),'rejected']);
    const coordinate = 'TOPIC T = CLASS Base = coord: COORD 0..100, 0..100; END Base; CLASS Child EXTENDS Base = coord (EXTENDED): MANDATORY; MANDATORY CONSTRAINT coord[1] > 0; END Child; END T;';
    rows.push([coordinate,'succeeded'],[coordinate.replace('coord[1]','coord[3]'),'rejected']);
    rows.push(['FUNCTION f(v: MANDATORY): BOOLEAN;','rejected'], ['FUNCTION f(v: BOOLEAN): MANDATORY;','rejected']);
    for (const [body,expected] of rows) { await verify(wrap(body),expected); mandatoryCases++; }
  }
  return mandatoryCases;
}

async function parameters({verify, verifySources}) {
  let parameterCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "x" VERSION "1" = ${body} END F.`;
    const cls = expr => `TOPIC T = CLASS A = MANDATORY CONSTRAINT ${expr}; END A; END T;`;
    for (const [body, expected] of [
      ['PARAMETER p: BOOLEAN; ' + cls('PARAMETER p'), 'succeeded'],
      ['DOMAIN p = TEXT*2; PARAMETER p: BOOLEAN; ' + cls('PARAMETER p'), 'succeeded'],
      ['PARAMETER p: TEXT; ' + cls('PARAMETER p'), 'rejected'],
      ['DOMAIN p = BOOLEAN; ' + cls('PARAMETER p'), 'rejected'],
      ['PARAMETER p: BOOLEAN; ' + cls('PARAMETER Missing.p'), 'rejected'],
      ['PARAMETER p: BOOLEAN; p: TEXT;', 'rejected'],
      ['DOMAIN Coord = COORD 0..100,0..100; Shape = AREA WITH (STRAIGHTS) VERTEX Coord WITHOUT OVERLAPS > 0.01; PARAMETER p: Shape;', 'rejected'],
      [cls('INTERLIS.isOfClass(THIS, >A)'), 'succeeded'],
      [cls('INTERLIS.isSubClass(INTERLIS.myClass(THIS), >A)'), 'succeeded'],
      [cls('INTERLIS.isOfClass(THIS, 123)'), 'rejected'],
      [cls('INTERLIS.isOfClass(>A, >A)'), 'rejected'],
      [cls('INTERLIS.isOfClass(ALL, >A)'), 'rejected'],
      [cls('INTERLIS.isOfClass(THIS)'), 'rejected'],
      [cls('INTERLIS.isSubClass(THIS, >A)'), 'rejected'],
      [cls('DEFINED(INTERLIS.myClass(123))'), 'rejected'],
      [cls('DEFINED(INTERLIS.myClass(ALL))'), 'rejected'],
      ['TOPIC T = STRUCTURE S = END S; CLASS A = s: S; MANDATORY CONSTRAINT INTERLIS.isOfClass(s, >S); END A; END T;', 'succeeded'],
      ['TOPIC T = CLASS A = END A; CLASS B EXTENDS A = END B; CLASS C = cls(TRANSIENT): CLASS RESTRICTION (A) := >B; END C; END T;', 'succeeded'],
      ['TOPIC T = CLASS A = END A; CLASS B = END B; CLASS C = cls(TRANSIENT): CLASS RESTRICTION (A) := >B; END C; END T;', 'rejected'],
      ['TOPIC T = STRUCTURE S = END S; CLASS C = cls(TRANSIENT): CLASS := >S; END C; END T;', 'rejected'],
      ['TOPIC T = OID AS INTERLIS.STANDARDOID; CLASS A = END A; CLASS B = END B; ASSOCIATION L = a -- A; b -- B; cls(TRANSIENT): CLASS := INTERLIS.myClass(a); path: ATTRIBUTE OF cls; END L; END T;', 'succeeded'],
      ['TOPIC T = CLASS C = cls: TEXT; path: ATTRIBUTE OF cls; END C; END T;', 'rejected'],
      ['FUNCTION f(objects: OBJECTS OF ANYCLASS; path: ATTRIBUTE OF @objects): BOOLEAN;', 'succeeded'],
      ['FUNCTION f(objects: NUMERIC; path: ATTRIBUTE OF @objects): BOOLEAN;', 'rejected'],
      ['FUNCTION f(objects: OBJECTS OF ANYCLASS; path: ATTRIBUTE OF @missing): BOOLEAN;', 'rejected'],
      ['FUNCTION f(a: ATTRIBUTE OF @b; b: ATTRIBUTE OF @a): BOOLEAN;', 'rejected'],
      ['TOPIC T = CLASS C = label: TEXT; path: ATTRIBUTE; MANDATORY CONSTRAINT path == >>label; END C; END T;', 'succeeded'],
      ['TOPIC T = CLASS C = label: TEXT*20; path(TRANSIENT): ATTRIBUTE RESTRICTION (TEXT*10) := >>label; END C; END T;', 'rejected']
    ]) { await verify(wrap(body), expected); parameterCases++; }
    await verify(wrap('PARAMETER p: BOOLEAN;').replace('CONTRACTED ', ''), version === '2.3' ? 'rejected' : 'succeeded'); parameterCases++;
    const imports = `INTERLIS ${version}; CONTRACTED MODEL A AT "x" VERSION "1" = PARAMETER p: BOOLEAN; END A. CONTRACTED MODEL B AT "x" VERSION "1" = PARAMETER p: TEXT; END B. `;
    const consumer = 'CONTRACTED MODEL F AT "x" VERSION "1" = IMPORTS UNQUALIFIED A, B; ' + cls('PARAMETER p') + ' END F.';
    for (const [body, expected] of [[consumer, 'succeeded'], [consumer.replace('UNQUALIFIED A', 'A'), 'rejected'], [consumer.replace('A, B', 'A, UNQUALIFIED B'), 'rejected']]) {
      await verify(imports + body, expected); parameterCases++;
    }
    const original = `INTERLIS ${version}; CONTRACTED MODEL Base AT "x" VERSION "1" = DOMAIN Flag = BOOLEAN; PARAMETER p: MANDATORY Flag; q: Flag; TOPIC T = CLASS C = MANDATORY CONSTRAINT PARAMETER p; END C; END T; END Base. `;
    const target = 'CONTRACTED MODEL F AT "x" VERSION "1" TRANSLATION OF Base ["1"] = DOMAIN Vlag = BOOLEAN; PARAMETER x: MANDATORY Vlag; y: Vlag; TOPIC U = CLASS D = MANDATORY CONSTRAINT PARAMETER x; END D; END U; END F.';
    for (const [body, expected] of [[target, 'succeeded'], [target.replace('x: MANDATORY', 'x:'), 'rejected'], [target.replace('PARAMETER x;', 'PARAMETER y;'), 'rejected']]) {
      await verify(original + body, expected); parameterCases++;
    }
    for (const first of [true, false]) {
      await verifySources([
        {sourceId: `memory:/${first ? 'a' : 'z'}.ili`, text: `INTERLIS ${version}; CONTRACTED MODEL Imported AT "x" VERSION "1" = DOMAIN Flag = BOOLEAN; PARAMETER p: Flag; END Imported.`},
        {sourceId: `memory:/${first ? 'z' : 'a'}.ili`, text: wrap('IMPORTS Imported; PARAMETER p: TEXT; ' + cls('PARAMETER Imported.p'))}
      ], 'succeeded'); parameterCases++;
    }
  }
  return parameterCases;
}

async function genericContexts({verify, verifySources}) {
  let contextCases = 0;
  const contextDomains = 'DOMAIN G (GENERIC) = COORD NUMERIC,NUMERIC; A = COORD 0..100,0..100; B = COORD 200..300,200..300; ';
  const contextTopic = (deferred = '') => `TOPIC T = ${deferred} CLASS C = p: G; END C; END T;`;
  const contextWrap = body => `INTERLIS 2.4; MODEL F AT "x" VERSION "1" = ${body} END F.`;
  for (const [body, expected] of [
    ['DOMAIN G (GENERIC) = COORD NUMERIC,0..100; A = COORD 200..300,0..100; CONTEXT c = G = A; ' + contextTopic(), 'succeeded'],
    ['DOMAIN G (GENERIC) = COORD NUMERIC,0..100; A = COORD 0..100,200..300; CONTEXT c = G = A; ' + contextTopic(), 'rejected'],
    ['DOMAIN G (GENERIC) = COORD 0..100,NUMERIC; A = COORD 0..100,200..300; CONTEXT c = G = A; ' + contextTopic(), 'succeeded'],
    [contextDomains + 'CONTEXT c = G = A; ' + contextTopic(), 'succeeded'],
    [contextDomains + 'CONTEXT c = G = A OR B; ' + contextTopic('DEFERRED GENERICS G;'), 'succeeded'],
    [contextDomains + contextTopic().replace('TOPIC T =', 'TOPIC T (ABSTRACT) ='), 'succeeded'],
    [contextDomains + contextTopic(), 'rejected'],
    [contextDomains + contextTopic('DEFERRED GENERICS G;'), 'rejected'],
    [contextDomains + 'CONTEXT c = G = A OR B; ' + contextTopic(), 'rejected'],
    [contextDomains + 'CONTEXT c = G = A OR B; ' + contextTopic('DEFERRED GENERICS G;').replace('p: G', 'p: A'), 'rejected'],
    [contextDomains + contextTopic('DEFERRED GENERICS A;'), 'rejected'],
    [contextDomains + contextTopic('DEFERRED GENERICS Missing;'), 'rejected'],
    [contextDomains + 'CONTEXT c = A = B; ' + contextTopic(), 'rejected'],
    [contextDomains + 'CONTEXT c = G = G; ' + contextTopic(), 'rejected'],
    [contextDomains + 'X = TEXT; CONTEXT c = G = X; ' + contextTopic(), 'rejected'],
    [contextDomains + 'X = COORD 0..100; CONTEXT c = G = X; ' + contextTopic(), 'rejected'],
    [contextDomains.replace('COORD NUMERIC,NUMERIC', 'COORD 0..100,NUMERIC') + 'CONTEXT c = G = B; ' + contextTopic(), 'rejected'],
    [contextDomains + 'X (ABSTRACT) = COORD NUMERIC,NUMERIC; CONTEXT c = G = X; ' + contextTopic(), 'rejected'],
    ['DOMAIN G (GENERIC) = TEXT;', 'rejected'],
    [contextDomains + 'CONTEXT c = Missing.G = A; ' + contextTopic(), 'rejected'],
    [contextDomains + 'CONTEXT c = G = A; G = B; ' + contextTopic(), 'rejected'],
    [contextDomains + 'TOPIC T = CONTEXT c = G = A; END T;', 'rejected'],
    [contextDomains + 'CONTEXT c = G = A; c = G = A;', 'rejected'],
    [contextDomains + 'CONTEXT c = G = A OR B; ' + contextTopic('DEFERRED GENERICS G;') + 'TOPIC U = CLASS D = p: G; END D; END U;', 'rejected'],
    [contextDomains + 'CONTEXT c = G = A OR B; STRUCTURE S = END S; STRUCTURE D EXTENDS S = p: POLYLINE WITH (STRAIGHTS) VERTEX G; END D; TOPIC T = DEFERRED GENERICS G; CLASS C = parts: BAG OF S; END C; END T;', 'succeeded'],
    [contextDomains + 'CONTEXT c = G = A OR B; STRUCTURE S = p: G; END S; TOPIC T = CLASS C = parts: LIST OF S; END C; END T;', 'rejected'],
    [contextDomains + 'H (GENERIC) = COORD NUMERIC,NUMERIC; CONTEXT c = G = A; H = B; d = G = A; ' + contextTopic(), 'succeeded'],
  ]) { await verify(contextWrap(body), expected); contextCases++; }
  await verify(contextWrap(contextDomains + 'CONTEXT c = G = A; ' + contextTopic('DEFERRED GENERICS G;')).replace('INTERLIS 2.4', 'INTERLIS 2.3'), 'rejected'); contextCases++;
  const contextBase = `INTERLIS 2.4; MODEL Base AT "x" VERSION "1" = ${contextDomains} CONTEXT c = G = A OR B; ${contextTopic('DEFERRED GENERICS G;')} END Base. `;
  const contextDerived = 'MODEL F AT "x" VERSION "1" = IMPORTS Base; DOMAIN Small EXTENDS Base.A = COORD 10..20,10..20; CONTEXT c = Base.G = Small; TOPIC U EXTENDS Base.T = END U; END F.';
  for (const [body, expected] of [
    [contextDerived, 'succeeded'],
    [contextDerived.replace('EXTENDS Base.A', 'EXTENDS Base.G'), 'rejected'],
    [contextDerived.replace('IMPORTS Base;', ''), 'rejected'],
    [contextDerived.replace('10..20,10..20', '0..200,0..200'), 'rejected']
  ]) { await verify(contextBase + body, expected); contextCases++; }
  for (const reverse of [false, true]) {
    await verifySources([
      {sourceId: reverse ? 'memory:/z-context.ili' : 'memory:/a-context.ili', text: contextBase},
      {sourceId: reverse ? 'memory:/a-use.ili' : 'memory:/z-use.ili', text: 'INTERLIS 2.4; ' + contextDerived}
    ], 'succeeded'); contextCases++;
  }
  return contextCases;
}

async function temporalTypes({verify, verifySources}) {
  let temporalCases = 0;
  for (const version of ['2.3', '2.4']) {
    const bound = (domain, lo, hi) => `DOMAIN D = FORMAT INTERLIS.${domain} "${lo}" .. "${hi}";`;
    const cases = [
      [bound('XMLDate', '2010-1-1', '2110-12-31'), version === '2.3' ? 'succeeded' : 'rejected'],
      [bound('XMLTime', '00:0:0.000', '23:59:59.999'), version === '2.3' ? 'succeeded' : 'rejected'],
      [bound('XMLDateTime', '2010-01-01T00:00:00.000', '2110-12-31T23:59:59.999'), 'succeeded'],
      [bound('XMLDate', '2010-02-31', '2110-12-31'), 'succeeded'],
      [bound('XMLDate', '1581-01-01', '2110-12-31'), 'rejected'],
      [bound('XMLTime', '0:00:00.000', '23:59:59.999'), 'rejected'],
      [bound('XMLTime', '24:00:00.000', '23:59:59.999'), 'rejected'],
      [bound('XMLTime', '00:60:00.000', '23:59:59.999'), 'rejected'],
      [bound('XMLTime', '00:00:60.000', '23:59:59.999'), 'rejected'],
      [bound('XMLTime', '00:00:00.00', '23:59:59.999'), 'rejected'],
      ['STRUCTURE S = date: INTERLIS.GregorianDate; END S; DOMAIN D = FORMAT BASED ON S (date/INTERLIS.XMLDate) "2010-01-01" .. "2110-12-31";', 'succeeded'],
      ['DOMAIN D = FORMAT BASED ON INTERLIS.GregorianDate (Year/4 "-" Month/2 "-" Day/2) "2010-1-1" .. "2110-12-31";', 'rejected'],
      ['CLASS C = date: INTERLIS.XMLDate; MANDATORY CONSTRAINT date == "2010-13-01"; END C;', 'rejected'],
      ['STRUCTURE S EXTENDS INTERLIS.UnknownBase = END S;', 'rejected'],
      ['CLASS C (ABSTRACT) EXTENDS INTERLIS.UnknownBase = END C;', 'rejected'],
      ['DOMAIN D EXTENDS INTERLIS.XMLDate = "2010-01-01" .. "2110-12-31";', 'succeeded'],
      ['STRUCTURE S EXTENDS INTERLIS.GregorianDate = extra:0..9; END S; DOMAIN D EXTENDS INTERLIS.XMLDate = FORMAT BASED ON S (INHERITANCE "/" extra) "2010-01-01/0" .. "2110-12-31/9";', 'succeeded']
    ];
    if (version === '2.4') cases.push(['CLASS C = date: DATE; time: TIMEOFDAY; stamp: DATETIME; MANDATORY CONSTRAINT date == "2010-1-1"; END C;', 'rejected']);
    for (const [body, expected] of cases) { await verify(`INTERLIS ${version}; MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`, expected); temporalCases++; }
  }
  // Exact pinned original, including CRLF. Pin checked in the JVM contract.
  await verifySources([{sourceId: 'memory:/g2/FormattedType.ili', text: "INTERLIS 2.3;\r\n\r\nMODEL FormattedType\r\n\tAT \"http://www.interlis.ch/ili2c/tests/\" \r\n\tVERSION \"2017-05-23\" =\r\n\r\n    \r\n  TOPIC TopicA =\r\n    \r\n    CLASS ClassA1 =\r\n    \tattr1 : FORMAT INTERLIS.XMLDate \"2010-1-1\" .. \"2110-12-31\";\r\n    \tattr2 : FORMAT INTERLIS.XMLDate \"2010-1-1\" .. \"2110-1-1\";\r\n    END ClassA1;\r\n    \r\n    \r\n  END TopicA;\r\n\r\nEND FormattedType.\r\n\r\n"}], 'succeeded', ['FormattedType']);
  temporalCases++;
  return temporalCases;
}

async function predefinedBinding({call, verify, verifySources}) {
  let predefinedBindingCases = 0;
  for (const version of ['2.3','2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const cases = [
      ['TOPIC T=CLASS C=value:INTERLIS.TypoDomain; END C; END T;', 'rejected'],
      ['TOPIC T=CLASS C=value:INTERLIS.INTERLIS_1_DATE; END C; END T;', 'succeeded'],
      ['TOPIC T=CLASS C=value:INTERLIS.HALIGNMENT; END C; END T;', 'succeeded'],
      ['TOPIC T=CLASS C=value:INTERLIS.VALIGNMENT; END C; END T;', 'succeeded'],
      ['DOMAIN D EXTENDS INTERLIS.INTERLIS_1_DATE=TEXT*8;', 'rejected'],
      ['DOMAIN D(FINAL)=TEXT*8; E EXTENDS D=TEXT*8;', 'rejected'],
      ['DOMAIN D(FINAL)=TEXT*8; TOPIC T=CLASS C=value:D; END C; END T;', 'succeeded'],
      ['FUNCTION f(v:NUMERIC):BOOLEAN; TOPIC T=CLASS C=MANDATORY CONSTRAINT f(1); END C; END T;', 'succeeded'],
      ['FUNCTION f(v:NUMERIC):BOOLEAN; TOPIC T=CLASS C=MANDATORY CONSTRAINT F.f(1); END C; END T;', 'succeeded'],
      ['FUNCTION f(v:NUMERIC):BOOLEAN; TOPIC T=CLASS C=MANDATORY CONSTRAINT Missing.f(1); END C; END T;', 'rejected'],
      ['DOMAIN D=(a,b); TOPIC T=CLASS C=value:ALL OF F.D; END C; END T;', 'succeeded'],
      ['DOMAIN D=(a,b); TOPIC T=CLASS C=value:ALL OF Missing.D; END C; END T;', 'rejected'],
      ['TOPIC T=CLASS C=value:ALL OF INTERLIS.NoSuchEnum; END C; END T;', 'rejected']
    ];
    for (const [body, expected] of cases) { await verify(wrap(body), expected); predefinedBindingCases++; }
    for (const reverse of [false,true]) {
      const base = `INTERLIS ${version}; CONTRACTED MODEL Base AT "https://example.org" VERSION "1" = DOMAIN D=(a,b); FUNCTION f(v:NUMERIC):BOOLEAN; END Base.`;
      await verifySources([
        {sourceId:reverse?'memory:/z-base.ili':'memory:/a-base.ili',text:base},
        {sourceId:reverse?'memory:/a-use.ili':'memory:/z-use.ili',text:wrap('IMPORTS UNQUALIFIED Base; TOPIC T=CLASS C=value:ALL OF Base.D; date:INTERLIS.INTERLIS_1_DATE; MANDATORY CONSTRAINT Base.f(1) AND f(1); END C; END T;')}
      ], 'succeeded'); predefinedBindingCases++;
    }
    for (const qualified of [false,true]) {
      const base = wrap('FUNCTION f(v:NUMERIC):BOOLEAN;').replace('MODEL F','MODEL Base').replace('END F.','END Base.');
      const other = base.replace('MODEL Base','MODEL Other').replace('END Base.','END Other.');
      const use = wrap(`IMPORTS UNQUALIFIED Base, UNQUALIFIED Other; TOPIC T=CLASS C=MANDATORY CONSTRAINT ${qualified?'Base.f':'f'}(1); END C; END T;`);
      await verifySources([{sourceId:'memory:/base.ili',text:base},{sourceId:'memory:/other.ili',text:other},{sourceId:'memory:/use.ili',text:use}], qualified?'succeeded':'rejected');
      predefinedBindingCases++;
    }
    const {sessionId} = await call('openSession');
    let revision;
    try {
      for (const name of ['INTERLIS_1_DATE','TypoDomain','INTERLIS_1_DATE']) {
        const updated = await call('updateSource', sessionId, {
          sourceId:'memory:/e1-edit.ili', expectation:revision === undefined ? {kind:'absent'} : {kind:'at',revision},
          change:{kind:'replace',text:wrap(`TOPIC T=CLASS C=value:INTERLIS.${name}; END C; END T;`)}
        });
        revision = updated.sourceRevision;
        const compiled = await call('compile', sessionId, {
          expectedWorkspaceRevision:updated.workspaceRevision, roots:[{kind:'byName',modelName:'F'}]
        });
        if (compiled.outcome !== (name === 'TypoDomain' ? 'rejected' : 'succeeded')) throw new Error(JSON.stringify(compiled));
        predefinedBindingCases++;
      }
    } finally { await call('closeSession', sessionId); }
  }
  return predefinedBindingCases;
}

